// ─── File: FacadeAdapterDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.onboard;

import java.util.logging.*;

public class FacadeAdapterDemo {
    private static final Logger log = Logger.getLogger(FacadeAdapterDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ADAPTER: wrap the mismatched vendor API behind our interface.
        CreditScoreProvider credit = new CibilAdapter(new CibilLegacyApi());

        // FACADE: one simple entry point over four subsystem services.
        AccountOpeningFacade facade = new AccountOpeningFacade(
                new KycService(), new AccountRepository(),
                new CardIssuer(), new NotificationService(), credit);

        log.info("=== FACADE: open account via ONE method ===");
        facade.openAccount("SAV2001", "Rajesh", "ABCDE1234F");
    }
}

// ─── Subsystem classes (each does ONE part) ───
class KycService {
    private static final Logger log = Logger.getLogger(KycService.class.getName());
        boolean verify(String pan) { log.info(() -> "KYC verified PAN " + pan);
        return true; }
}
class AccountRepository {
