}

// ─── facade/AccountOpeningFacade.java ───
// FACADE: hides subsystem complexity behind ONE simple method.
class AccountOpeningFacade {
    private static final Logger log = Logger.getLogger(AccountOpeningFacade.class.getName());
    private final KycService kyc;
    private final AccountRepository repo;
    private final CardIssuer cards;
    private final NotificationService notifier;
    private final CreditScoreProvider credit;

    AccountOpeningFacade(KycService kyc, AccountRepository repo, CardIssuer cards,
                         NotificationService notifier, CreditScoreProvider credit) {
            this.kyc = kyc;
            this.repo = repo
            this.cards = cards;
        this.notifier = notifier; this.credit = credit;
    }

    void openAccount(String id, String name, String pan) {
        if (!kyc.verify(pan)) { log.severe("KYC failed"); return; }
        int score = credit.getScore(pan);                 // uses the ADAPTER internally
        log.info(() -> "Credit score via adapter: " + score);
        repo.create(id, name);
        cards.issue(id);
        notifier.welcome(name);
        log.info(() -> "Account opening COMPLETE for " + name + " (single facade call)");
    }
}

// ─── credit/CreditScoreProvider.java ───  (OUR target interface)
interface CreditScoreProvider {
    int getScore(String pan);
}

// ─── credit/CibilLegacyApi.java ───  (vendor adaptee — WE CANNOT CHANGE IT)
class CibilLegacyApi {
    // Different method name, different shape than our interface.
    CibilResponse fetch(CibilRequest request) {
        CibilResponse r = new CibilResponse();
        r.rating = "A";       // vendor returns a letter rating + a raw number
        r.numericBand = 780;
        return r;
    }
}
class CibilRequest { String panNumber; }
class CibilResponse { String rating; int numericBand; }

// ─── credit/CibilAdapter.java ───
// ADAPTER: makes CibilLegacyApi satisfy our CreditScoreProvider interface.
class CibilAdapter implements CreditScoreProvider {
    private final CibilLegacyApi vendor; // object adapter: holds the adaptee
    CibilAdapter(CibilLegacyApi vendor) { this.vendor = vendor; }

    @Override public int getScore(String pan) {
        CibilRequest req = new CibilRequest();
        req.panNumber = pan;                 // translate OUR call → vendor's request
        CibilResponse resp = vendor.fetch(req);
        return resp.numericBand;             // translate vendor's response → our int
    }
}

// ─── util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
